import { Router, type IRouter } from "express";
import { db, salesTable, saleItemsTable, customersTable, productsTable, usersTable } from "@workspace/db";
import { requireAdmin } from "../middlewares/auth";
import { gte, sql } from "drizzle-orm";

const router: IRouter = Router();

router.get("/admin/overview", requireAdmin, async (req, res): Promise<void> => {
  try {
    const allSales = await db.select().from(salesTable);
    const allCustomers = await db.select().from(customersTable);
    const allProducts = await db.select().from(productsTable);
    const allUsers = await db.select().from(usersTable);
    const allItems = await db.select().from(saleItemsTable);

    const totalSalesVolume = allSales.reduce((s, x) => s + parseFloat(x.totalAmount), 0);
    const totalCommission = allSales.reduce((s, x) => s + (x as any).commissionAmount ? parseFloat((x as any).commissionAmount ?? "0") : 0, 0);
    const totalTransactions = allSales.length;

    const byMethod: Record<string, number> = { cash: 0, cash_on_delivery: 0, qr_payment: 0, debt: 0 };
    for (const s of allSales) {
      const m = (s as any).paymentMethod ?? (s.paymentType === "debt" ? "debt" : "cash");
      byMethod[m] = (byMethod[m] ?? 0) + 1;
    }

    const thirtyDaysAgo = new Date();
    thirtyDaysAgo.setDate(thirtyDaysAgo.getDate() - 30);
    const recentSales = allSales.filter(s => new Date(s.createdAt) >= thirtyDaysAgo);

    const commissionByDay: Record<string, number> = {};
    const volumeByDay: Record<string, number> = {};
    for (const s of recentSales) {
      const day = new Date(s.createdAt).toISOString().slice(0, 10);
      commissionByDay[day] = (commissionByDay[day] ?? 0) + parseFloat((s as any).commissionAmount ?? "0");
      volumeByDay[day] = (volumeByDay[day] ?? 0) + parseFloat(s.totalAmount);
    }

    const chartData = Object.entries(volumeByDay)
      .sort(([a], [b]) => a.localeCompare(b))
      .slice(-14)
      .map(([date, volume]) => ({
        date,
        volume,
        commission: commissionByDay[date] ?? 0,
      }));

    const topProducts: Record<number, { name: string; qty: number; revenue: number }> = {};
    for (const item of allItems) {
      if (!topProducts[item.productId]) topProducts[item.productId] = { name: item.productName, qty: 0, revenue: 0 };
      topProducts[item.productId].qty += item.quantity;
      topProducts[item.productId].revenue += parseFloat(item.total);
    }
    const topProductsList = Object.entries(topProducts)
      .map(([id, v]) => ({ id: Number(id), ...v }))
      .sort((a, b) => b.revenue - a.revenue)
      .slice(0, 10);

    const recentTransactions = allSales
      .sort((a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime())
      .slice(0, 20)
      .map(s => ({
        id: s.id,
        totalAmount: parseFloat(s.totalAmount),
        paymentType: s.paymentType,
        paymentMethod: (s as any).paymentMethod ?? "cash",
        commissionAmount: parseFloat((s as any).commissionAmount ?? "0"),
        createdAt: s.createdAt,
        customerId: s.customerId,
      }));

    res.json({
      totals: {
        salesVolume: totalSalesVolume,
        commission: totalCommission,
        transactions: totalTransactions,
        customers: allCustomers.length,
        products: allProducts.length,
        users: allUsers.length,
      },
      byMethod,
      chartData,
      topProducts: topProductsList,
      recentTransactions,
      customers: allCustomers.slice(0, 50).map(c => ({
        id: c.id,
        name: c.name,
        phone: c.phone,
        address: c.address,
        createdAt: c.createdAt,
        totalPurchases: allSales.filter(s => s.customerId === c.id).reduce((sum, s) => sum + parseFloat(s.totalAmount), 0),
        transactionCount: allSales.filter(s => s.customerId === c.id).length,
      })),
      products: allProducts.map(p => ({
        id: p.id,
        name: p.name,
        category: p.category,
        stock: p.stock,
        price: parseFloat(p.price),
        costPrice: parseFloat(p.costPrice),
        barcode: p.barcode,
      })),
      users: allUsers.map(u => ({
        id: u.id,
        name: u.name,
        username: u.username,
        role: u.role,
        createdAt: u.createdAt,
      })),
    });
  } catch (err) {
    res.status(500).json({ message: "Server error", err: String(err) });
  }
});

export default router;

