import { useState, useEffect, useRef } from "react";
import { useAuth } from "@/contexts/AuthContext";
import { motion, AnimatePresence } from "framer-motion";
import { useTranslation } from "react-i18next";
import i18n from "@/i18n";
import {
  Zap, Check, ChevronDown, ChevronLeft, ChevronRight,
  Package, ShoppingBag, Truck, Settings, Share2, UtensilsCrossed,
  Building2, HeartPulse, ShoppingCart, Brain, Star,
  User, Mail, Phone, FileText, Lock, Eye, EyeOff,
  Globe, MapPin, Info, Sparkles, TrendingUp, Upload,
  Factory, Layers, CheckCircle2, ArrowRight, ExternalLink,
} from "lucide-react";

/* ─── Constants ──────────────────────────────────────────────────────────── */

const LANGUAGES = [
  { code: "ku", label: "کوردی" },
  { code: "ar", label: "العربية" },
  { code: "en", label: "English" },
];

const PHONE_PREFIXES = [
  { code: "+964", flag: "🇮🇶", label: "IQ" },
  { code: "+90",  flag: "🇹🇷", label: "TR" },
  { code: "+98",  flag: "🇮🇷", label: "IR" },
  { code: "+1",   flag: "🇺🇸", label: "US" },
  { code: "+44",  flag: "🇬🇧", label: "GB" },
  { code: "+49",  flag: "🇩🇪", label: "DE" },
];

const GOVERNORATES = [
  "erbil","sulaymaniyah","duhok","halabja","kirkuk",
  "baghdad","nineveh","basra","najaf","karbala",
  "anbar","babylon","diyala","qadisiyah","maysan",
  "muthanna","dhiqar","salahadin","wasit",
];

const ACCOUNT_TYPES = [
  { key: "supplier",     icon: Package,         color: "#2563EB" },
  { key: "supermarket",  icon: ShoppingBag,     color: "#7C3AED" },
  { key: "transport",    icon: Truck,           color: "#059669" },
  { key: "manufacturer", icon: Factory,         color: "#DC2626" },
  { key: "distributor",  icon: Share2,          color: "#D97706" },
  { key: "restaurant",   icon: UtensilsCrossed, color: "#DB2777" },
  { key: "hotel",        icon: Building2,       color: "#0891B2" },
  { key: "pharmacy",     icon: HeartPulse,      color: "#16A34A" },
  { key: "buyer",        icon: ShoppingCart,    color: "#9333EA" },
];

const SECTORS = [
  "food_beverage","agriculture","construction","healthcare",
  "technology","education","retail","logistics","energy",
  "finance","hospitality","manufacturing","textile","electronics","automotive",
];

const BUSINESS_TYPES = [
  "sole_proprietorship","partnership","llc","corporation","cooperative","ngo",
];

const INDUSTRY_SECTORS = [
  "food_beverage","agriculture","technology","healthcare","retail","logistics",
  "construction","education","energy","finance","hospitality","manufacturing",
];

const ROLE_MAP: Record<string, "supplier" | "buyer" | "driver"> = {
  supplier: "supplier", supermarket: "buyer", transport: "driver",
  manufacturer: "supplier", distributor: "supplier", restaurant: "buyer",
  hotel: "buyer", pharmacy: "buyer", buyer: "buyer",
};

/* ─── Animated Canvas Background ─────────────────────────────────────────── */
type IconType = "truck" | "cart" | "box" | "store";

function drawIcon(ctx: CanvasRenderingContext2D, type: IconType, cx: number, cy: number, size: number, alpha: number) {
  const s = size / 24;
  ctx.save();
  ctx.translate(cx - size / 2, cy - size / 2);
  ctx.strokeStyle = `rgba(186,220,255,${alpha})`;
  ctx.lineWidth = 2 / s; ctx.lineCap = "round"; ctx.lineJoin = "round";
  ctx.scale(s, s);
  if (type === "truck") {
    ctx.beginPath(); ctx.rect(1,6,13,10); ctx.stroke();
    ctx.beginPath(); ctx.moveTo(14,8); ctx.lineTo(21,8); ctx.lineTo(23,11); ctx.lineTo(23,16); ctx.lineTo(14,16); ctx.closePath(); ctx.stroke();
    ctx.beginPath(); ctx.arc(5,18,2,0,Math.PI*2); ctx.stroke();
    ctx.beginPath(); ctx.arc(19,18,2,0,Math.PI*2); ctx.stroke();
  } else if (type === "cart") {
    ctx.beginPath(); ctx.moveTo(1,1); ctx.lineTo(5,1); ctx.lineTo(8.5,14); ctx.lineTo(20.5,14); ctx.lineTo(22,5); ctx.lineTo(6,5); ctx.stroke();
    ctx.beginPath(); ctx.arc(9,20,1.5,0,Math.PI*2); ctx.stroke();
    ctx.beginPath(); ctx.arc(20,20,1.5,0,Math.PI*2); ctx.stroke();
  } else if (type === "box") {
    ctx.beginPath(); ctx.rect(2,8,20,13); ctx.stroke();
    ctx.beginPath(); ctx.moveTo(2,8); ctx.lineTo(12,3); ctx.lineTo(22,8); ctx.stroke();
    ctx.beginPath(); ctx.moveTo(12,8); ctx.lineTo(12,21); ctx.stroke();
  } else {
    ctx.beginPath(); ctx.rect(2,10,20,11); ctx.stroke();
    ctx.beginPath(); ctx.moveTo(1,10); ctx.lineTo(12,3); ctx.lineTo(23,10); ctx.stroke();
    ctx.beginPath(); ctx.rect(9,15,6,6); ctx.stroke();
  }
  ctx.restore();
}

function AnimatedBackground() {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  useEffect(() => {
    const canvas = canvasRef.current; if (!canvas) return;
    const ctx = canvas.getContext("2d"); if (!ctx) return;
    let raf: number;
    const resize = () => { canvas.width = window.innerWidth; canvas.height = window.innerHeight; };
    resize(); window.addEventListener("resize", resize);
    const TYPES: IconType[] = ["truck","cart","box","store"];
    const icons = Array.from({ length: 18 }, (_, i) => ({
      x: Math.random()*window.innerWidth, y: Math.random()*window.innerHeight,
      vx: (Math.random()-.5)*.3, vy: (Math.random()-.5)*.3,
      size: 16+Math.random()*12, type: TYPES[i%4],
      pulse: Math.random()*Math.PI*2, pulseSpeed: .015+Math.random()*.02,
      baseAlpha: .4+Math.random()*.25,
    }));
    const orbs = [
      { x:window.innerWidth*.18, y:window.innerHeight*.28, vx:.14, vy:.09, r:280 },
      { x:window.innerWidth*.82, y:window.innerHeight*.72, vx:-.11, vy:-.08, r:220 },
      { x:window.innerWidth*.55, y:window.innerHeight*.05, vx:.07, vy:.16, r:180 },
    ];
    let tick = 0;
    const draw = () => {
      const W = canvas.width, H = canvas.height;
      ctx.fillStyle = "#020C1C"; ctx.fillRect(0,0,W,H);
      const z1 = ctx.createRadialGradient(W*.22,H*.5,0,W*.22,H*.5,W*.45);
      z1.addColorStop(0,"rgba(29,78,216,.35)"); z1.addColorStop(1,"rgba(10,30,80,0)");
      ctx.fillStyle = z1; ctx.fillRect(0,0,W,H);
      const z2 = ctx.createRadialGradient(W*.88,H*.1,0,W*.88,H*.1,W*.35);
      z2.addColorStop(0,"rgba(6,182,212,.18)"); z2.addColorStop(1,"rgba(0,0,0,0)");
      ctx.fillStyle = z2; ctx.fillRect(0,0,W,H);
      for (const orb of orbs) {
        orb.x+=orb.vx; orb.y+=orb.vy;
        if(orb.x<-orb.r||orb.x>W+orb.r) orb.vx*=-1;
        if(orb.y<-orb.r||orb.y>H+orb.r) orb.vy*=-1;
        const g = ctx.createRadialGradient(orb.x,orb.y,0,orb.x,orb.y,orb.r);
        g.addColorStop(0,"rgba(99,179,255,.18)"); g.addColorStop(1,"rgba(29,78,216,0)");
        ctx.fillStyle=g; ctx.beginPath(); ctx.arc(orb.x,orb.y,orb.r,0,Math.PI*2); ctx.fill();
      }
      const alpha = .12+.04*Math.sin(tick*.007);
      ctx.textAlign="center"; ctx.textBaseline="middle";
      [{ x:.15,y:.2,s:70 },{ x:.82,y:.75,s:50 },{ x:.5,y:.92,s:40 }].forEach(wm=>{
        ctx.font=`bold ${wm.s}px system-ui`; ctx.fillStyle=`rgba(147,197,253,${alpha})`;
        ctx.fillText("LinQi",W*wm.x,H*wm.y);
      });
      for (const ic of icons) {
        ic.x+=ic.vx; ic.y+=ic.vy; ic.pulse+=ic.pulseSpeed;
        if(ic.x<-ic.size) ic.x=W+ic.size; if(ic.x>W+ic.size) ic.x=-ic.size;
        if(ic.y<-ic.size) ic.y=H+ic.size; if(ic.y>H+ic.size) ic.y=-ic.size;
      }
      const MAX = 150;
      for(let i=0;i<icons.length;i++) for(let j=i+1;j<icons.length;j++){
        const dx=icons[i].x-icons[j].x, dy=icons[i].y-icons[j].y, d2=dx*dx+dy*dy;
        if(d2<MAX*MAX){ const d=Math.sqrt(d2);
          ctx.strokeStyle=`rgba(96,165,250,${(1-d/MAX)*.4})`; ctx.lineWidth=.8;
          ctx.beginPath(); ctx.moveTo(icons[i].x,icons[i].y); ctx.lineTo(icons[j].x,icons[j].y); ctx.stroke();
        }
      }
      for(const ic of icons) drawIcon(ctx,ic.type,ic.x,ic.y,ic.size,ic.baseAlpha+.07*Math.sin(ic.pulse));
      tick++; raf=requestAnimationFrame(draw);
    };
    draw();
    return () => { cancelAnimationFrame(raf); window.removeEventListener("resize",resize); };
  },[]);
  return <canvas ref={canvasRef} className="fixed inset-0 w-full h-full" style={{zIndex:0}} />;
}

/* ─── Progress Tracker ───────────────────────────────────────────────────── */
function ProgressBar({ step, total }: { step: number; total: number }) {
  const { t } = useTranslation();
  const labels = [t("onboard.step1Label"), t("onboard.step2Label"), t("onboard.step3Label"), t("onboard.step4Label")];
  return (
    <div className="px-6 pt-6 pb-4">
      <div className="flex items-start justify-between relative">
        <div className="absolute top-4 start-8 end-8 h-0.5 bg-gray-200 z-0">
          <motion.div className="h-full bg-blue-500 rounded-full" style={{ width: `${((step - 1) / (total - 1)) * 100}%` }}
            transition={{ duration: 0.4 }} />
        </div>
        {Array.from({ length: total }, (_, i) => {
          const n = i + 1;
          const done = n < step, active = n === step;
          return (
            <div key={n} className="flex flex-col items-center z-10 flex-1">
              <motion.div className={`w-8 h-8 rounded-full flex items-center justify-center text-sm font-bold border-2 transition-all duration-300 ${
                done ? "bg-blue-500 border-blue-500 text-white" : active ? "bg-white border-blue-500 text-blue-600" : "bg-white border-gray-300 text-gray-400"
              }`} layout>
                {done ? <Check className="w-4 h-4" /> : <span>{n}</span>}
              </motion.div>
              <p className={`text-[10px] mt-1.5 text-center font-medium leading-tight max-w-[64px] ${active ? "text-blue-600" : done ? "text-blue-400" : "text-gray-400"}`}>
                {labels[i]}
              </p>
            </div>
          );
        })}
      </div>
    </div>
  );
}

/* ─── Shared Input ───────────────────────────────────────────────────────── */
function Input({ label, error, icon: Icon, type = "text", ...props }: any) {
  const [show, setShow] = useState(false);
  const isPass = type === "password";
  return (
    <div>
      {label && <label className="block text-xs font-semibold text-gray-600 mb-1.5 uppercase tracking-wide">{label}</label>}
      <div className="relative">
        {Icon && <Icon className="absolute start-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400 pointer-events-none" />}
        <input type={isPass ? (show ? "text" : "password") : type} {...props}
          className={`w-full ${Icon ? "ps-9" : "ps-3.5"} ${isPass ? "pe-10" : "pe-3.5"} py-2.5 rounded-xl border text-sm text-gray-800 placeholder:text-gray-400 outline-none transition-all focus:ring-2 focus:ring-blue-100 focus:border-blue-400 bg-white ${error ? "border-red-300 bg-red-50" : "border-gray-200"}`} />
        {isPass && (
          <button type="button" onClick={() => setShow(v => !v)} className="absolute end-3 top-1/2 -translate-y-1/2 text-gray-400 hover:text-gray-600">
            {show ? <EyeOff className="w-4 h-4" /> : <Eye className="w-4 h-4" />}
          </button>
        )}
      </div>
      {error && <p className="text-[11px] text-red-500 mt-1">{error}</p>}
    </div>
  );
}

function Select({ label, error, children, ...props }: any) {
  return (
    <div>
      {label && <label className="block text-xs font-semibold text-gray-600 mb-1.5 uppercase tracking-wide">{label}</label>}
      <div className="relative">
        <select {...props} className={`w-full appearance-none ps-3.5 pe-9 py-2.5 rounded-xl border text-sm text-gray-800 outline-none transition-all focus:ring-2 focus:ring-blue-100 focus:border-blue-400 bg-white cursor-pointer ${error ? "border-red-300 bg-red-50" : "border-gray-200"}`}>
          {children}
        </select>
        <ChevronDown className="absolute end-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400 pointer-events-none" />
      </div>
      {error && <p className="text-[11px] text-red-500 mt-1">{error}</p>}
    </div>
  );
}

/* ─── Step 1: Company Details ─────────────────────────────────────────────── */
function Step1({ data, setData, errors, onNext }: any) {
  const { t } = useTranslation();
  const [prefix, setPrefix] = useState("+964");
  const [showPrefix, setShowPrefix] = useState(false);

  return (
