/* ─── Main Register ───────────────────────────────────────────────────────── */
export default function Register() {
  const { register } = useAuth();
  const { t } = useTranslation();
  const [lang, setLang] = useState(i18n.language);
  const [step, setStep] = useState(1);
  const [success, setSuccess] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [errors, setErrors] = useState<Record<string, string>>({});

  const [step1, setStep1] = useState({ companyName: "", email: "", phone: "", regNumber: "", password: "", confirmPassword: "" });
  const [step2, setStep2] = useState({ accountType: "" });
  const [step3, setStep3] = useState({ businessType: "", industrySector: "", governorate: "", city: "", address: "", website: "", description: "" });
  const [step4, setStep4] = useState({ sectors: [] as string[] });

  const switchLang = (code: string) => {
    i18n.changeLanguage(code); setLang(code);
    document.documentElement.dir = code === "ku" || code === "ar" ? "rtl" : "ltr";
    document.documentElement.lang = code;
  };

  const validateStep1 = () => {
    const e: Record<string, string> = {};
    if (!step1.companyName.trim()) e.companyName = t("onboard.errRequired");
    if (!step1.email.trim() || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(step1.email)) e.email = t("onboard.errEmail");
    if (!step1.phone.trim() || step1.phone.replace(/\D/g,"").length < 7) e.phone = t("onboard.errPhone");
    if (!step1.regNumber.trim()) e.regNumber = t("onboard.errRequired");
    if (!step1.password || step1.password.length < 6) e.password = t("onboard.errPassword");
    if (step1.password !== step1.confirmPassword) e.confirmPassword = t("onboard.errMatch");
    return e;
  };
  const validateStep2 = () => {
    if (!step2.accountType) return { accountType: t("onboard.errSelectType") };
    return {};
  };

  const handleNext1 = () => { const e = validateStep1(); if (Object.keys(e).length) { setErrors(e); return; } setErrors({}); setStep(2); };
  const handleNext2 = () => { const e = validateStep2(); if (Object.keys(e).length) { setErrors(e); return; } setErrors({}); setStep(3); };
  const handleNext3 = () => { setErrors({}); setStep(4); };

  const handleSubmit = async () => {
    setIsLoading(true);
    try {
      await new Promise(r => setTimeout(r, 900));
      setSuccess(true);
      await new Promise(r => setTimeout(r, 600));
      await register({
        fullName: step1.companyName,
        email: step1.email,
        phone: step1.phone,
        nationalId: step1.regNumber,
        role: ROLE_MAP[step2.accountType] ?? "buyer",
      });
    } catch (err: any) {
      setErrors({ submit: err.message ?? t("auth.error") });
      setIsLoading(false);
    }
  };

  const slideVariants = {
    enter: (dir: number) => ({ x: dir > 0 ? 40 : -40, opacity: 0 }),
    center: { x: 0, opacity: 1 },
    exit: (dir: number) => ({ x: dir > 0 ? -40 : 40, opacity: 0 }),
  };
  const [dir, setDir] = useState(1);
  const goNext = (fn: () => void) => { setDir(1); fn(); };
  const goBack = () => { setDir(-1); setStep(s => s - 1); };

  return (
    <div className="relative min-h-screen flex items-center justify-center p-4 overflow-hidden">
      <AnimatedBackground />

      <div className="fixed top-4 end-4 flex gap-1.5 z-20">
        {LANGUAGES.map(l => (
          <button key={l.code} onClick={() => switchLang(l.code)}
            className={`px-3 py-1.5 rounded-xl text-xs font-semibold transition-all ${lang === l.code ? "bg-blue-500 text-white shadow-lg shadow-blue-500/40" : "bg-white/10 text-white hover:bg-white/20 border border-white/15 backdrop-blur-sm"}`}>
            {l.label}
          </button>
        ))}
      </div>

      <motion.div initial={{ opacity: 0, y: 28 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.5 }}
        className="relative w-full max-w-xl z-10">
        <div className="rounded-3xl bg-white shadow-2xl shadow-black/20 overflow-hidden border border-white/60">
          {/* Header */}
          <div className="flex items-center gap-3 px-6 pt-6 pb-0">
            <div className="w-9 h-9 rounded-xl bg-blue-600 flex items-center justify-center shadow-md shadow-blue-300">
              <Zap className="w-5 h-5 text-white" />
            </div>
            <div>
              <p className="text-[10px] text-blue-400 font-mono uppercase tracking-widest leading-none">LinQi Platform</p>
              <h1 className="text-base font-extrabold text-gray-900 leading-tight">
                {success ? t("onboard.regComplete") : t("onboard.regTitle")}
              </h1>
            </div>
          </div>

          {/* Progress */}
          {!success && <ProgressBar step={step} total={4} />}

          {/* Steps */}
          <AnimatePresence mode="wait" custom={dir}>
            {success ? (
              <motion.div key="success" initial={{ opacity: 0, scale: .95 }} animate={{ opacity: 1, scale: 1 }} transition={{ duration: .35 }}>
                <SuccessOverlay companyName={step1.companyName} onGoToTerminal={handleSubmit} />
              </motion.div>
            ) : (
              <motion.div key={`step-${step}`} custom={dir} variants={slideVariants} initial="enter" animate="center" exit="exit"
                transition={{ duration: .28, ease: "easeInOut" }}>
                {step === 1 && <Step1 data={step1} setData={setStep1} errors={errors} onNext={() => goNext(handleNext1)} />}
                {step === 2 && <Step2 data={step2} setData={setStep2} errors={errors} onNext={() => goNext(handleNext2)} onBack={goBack} />}
                {step === 3 && <Step3 data={step3} setData={setStep3} errors={errors} onNext={() => goNext(handleNext3)} onBack={goBack} />}
                {step === 4 && <Step4 data={step4} setData={setStep4} onSubmit={handleSubmit} onBack={goBack} isLoading={isLoading} />}
              </motion.div>
            )}
          </AnimatePresence>

          {errors.submit && (
            <p className="text-center text-xs text-red-500 pb-4 px-6">{errors.submit}</p>
          )}
        </div>

        <p className="text-center text-xs text-slate-400 mt-4">{t("onboard.terms")}</p>
      </motion.div>
    </div>
  );
}

